def make_design(knobs, rng):
    n = 12
    k = int(knobs['k'])
    rS = int(knobs['rS'])
    dS = 1
    perm = rng.permutation(n)
    early = set(int(x) for x in perm[:n // 2])
    A, B, C = [], [], []
    for w in range(n):
        r, d = w, n + w
        if w in early:
            for _ in range(rS):
                A.append([[w], [r]])
            for _ in range(dS):
                C.append([[w], [d]])
        else:
            for _ in range(dS):
                A.append([[w], [d]])
            for _ in range(rS):
                C.append([[w], [r]])
        for _ in range(k):
            objs = [r, d]
            if rng.random() < 0.5:
                objs = [d, r]
            B.append([[w], objs])
    trials = []
    for ph in (A, B, C):
        idx = rng.permutation(len(ph))
        trials.extend([ph[int(i)] for i in idx])
    cands = list(range(2 * n))
    test = []
    for w in range(n):
        test.append({'word': w, 'candidates': cands, 'correct': w,
                     'group': 'early' if w in early else 'late'})
    ti = rng.permutation(n)
    test = [test[int(i)] for i in ti]
    return {'arms': {'x': {'trials': trials, 'test': test}}}

